def test_prepared_fixture_is_valid_python_and_clean_frozen_git(tmp_path):
    args = _args(tmp_path)
    report = prepare(args)
    source = (args.root / "src" / "tasks.py").read_text(encoding="utf-8")
    ast.parse(source)
    assert report["task_count"] == 50
    assert len(report["base_commit"]) == 40
    manifest = json.loads(args.output.read_text(encoding="utf-8"))
    assert manifest["schema"] == "hl-loop-formal-tasks/v2"
    assert manifest["evaluation_protocol"] == "hl-loop.evaluation.v2"
